const int32_t i03 = i3 - args.lp3;
const int32_t i02 = i2 - args.lp2;
const int32_t i01 = i1 - args.lp1;

const bool row_in = i01 >= 0 && i01 < args.ne01 &&
                    i02 >= 0 && i02 < args.ne02 &&
                    i03 >= 0 && i03 < args.ne03;

// a destination row outside the source is all zeros; the base pointer is clamped so it
// stays inside the source buffer in that case - row_in is what decides correctness
const int32_t j03 = row_in ? i03 : 0;
const int32_t j02 = row_in ? i02 : 0;
const int32_t j01 = row_in ? i01 : 0;

// walk src0 through nb00 rather than assuming an element stride of sizeof(T): the CPU
// kernel already does, and a permuted src0 (nb00 != sizeof(float)) reaches this kernel
// for real - qwen3_tts's causal_conv1d pads a BCT view. For the float4 variant one
// element spans four floats, hence the sizeof(T)/sizeof(float) factor.
const uint64_t sb00 = args.nb00*(sizeof(T)/sizeof(float));

device const char * src0_row = src0 + j03*args.nb03 + j02*args.nb02 + j01*args.nb01;
device       T *    dst_ptr  = (device T *) (dst + i3*args.nb3 + i2*args.nb2 + i1*args.nb1);

