    const int32_t i0 = k0*1024 + tpitg.x + l0;
    if (i0 >= args.ne0) {
        break;
    }

    const int32_t i00 = i0 - args.lp0;

    if (row_in && i00 >= 0 && i00 < args.ne00) {
        dst_ptr[i0] = *((device const T *) (src0_row + i00*sb00));
    } else {
        dst_ptr[i0] = 0.0f;
    }
}
